:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#121528;
  --text:#e9ecff;
  --muted:#b7bce6;
  --faint:#8b91c7;
  --accent:#7dd3fc;
  --good:#86efac;
  --warn:#fbbf24;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b2150 0%, var(--bg) 55%);color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
.hdr{display:flex;gap:16px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
.hdr h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);max-width:78ch}
.gr{font-family: "Noto Serif", "Times New Roman", serif; font-variant-ligatures: none;}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;box-shadow:var(--shadow);margin:12px 0}
.controls label{display:block;color:var(--muted);margin-bottom:8px}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
input[type=text]{flex:1;min-width:240px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--text);outline:none}
input[type=text]:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.15)}
button{padding:10px 12px;border-radius:12px;border:1px solid rgba(255,255,255,.14);background:rgba(125,211,252,.14);color:var(--text);cursor:pointer}
button:hover{background:rgba(125,211,252,.20)}
button:active{transform:translateY(1px)}
button.ghost{background:rgba(255,255,255,.06)}
button.ghost:hover{background:rgba(255,255,255,.10)}
.hint{margin:8px 0 0;color:var(--faint);font-size:13px}
.out{display:grid;grid-template-columns:1.2fr 1fr;gap:12px;margin-top:12px}
@media (max-width:860px){.out{grid-template-columns:1fr}}
.card{border:1px solid var(--line);border-radius:14px;padding:12px;background:rgba(0,0,0,.12)}
.card h2{margin:0 0 8px;font-size:15px;color:var(--muted);font-weight:650}
.result{font-family:var(--mono);white-space:pre-wrap;background:rgba(0,0,0,.18);border:1px dashed rgba(255,255,255,.16);border-radius:12px;padding:10px;min-height:86px}
.transform{font-family:var(--mono);white-space:pre-wrap;background:rgba(0,0,0,.18);border:1px dashed rgba(255,255,255,.16);border-radius:12px;padding:10px;min-height:64px;margin-top:10px}
.small{margin:0;color:var(--faint);font-size:13px}
.legend{margin:8px 0 0;padding-left:18px;color:var(--muted)}
.tag{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.18);margin-right:6px;vertical-align:1px}
.tag.pure{background:rgba(134,239,172,.14);border-color:rgba(134,239,172,.35)}
.tag.bary{background:rgba(251,113,133,.12);border-color:rgba(251,113,133,.35)}
.tag.warn{background:rgba(251,191,36,.12);border-color:rgba(251,191,36,.35)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{border:1px solid var(--line);background:rgba(255,255,255,.06);padding:7px 10px;border-radius:999px;cursor:pointer;font-family:var(--gr,inherit)}
.chip:hover{background:rgba(255,255,255,.10)}
.ftr{margin-top:10px;color:var(--faint)}
input[type=text]{min-width:0;flex:1 1 220px;width:100%}.result,.transform{overflow-wrap:anywhere;white-space:pre-wrap}.card{min-width:0}button{max-width:100%;white-space:normal}.wrap{overflow-wrap:anywhere}

